/**
 * issue #105: opt-in, generation-aware replacement for the editor's Deploy
 * seam. Reuses lib/remoteDeployStorage.js's proven POST-/flows staging
 * mechanics (auth, no-rev, v2 full deploy, "never log credentials")
 * unchanged, and adds ONLY the minimum immutable-generation + readiness +
 * atomic-promotion wrapper described in issue #105 P1-P3 on top of it.
 *
 * Contract (mirrors lib/remoteDeployStorage.js's saveFlows contract, but
 * generation-aware):
 *   1. delegate.saveFlows()/getCredentials() run exactly as before -
 *      editor A's own local save/credentials handling is untouched.
 *   2. A NEW immutable generation for THIS deploy is built via the
 *      caller-supplied `buildGeneration(flows, credentials)` - typically
 *      wraps provisioning/locating runner B's already-running Admin API
 *      at a distinct target/activityTaskQueue/userDir. This module never
 *      launches processes itself (see README's "known limitations" for
 *      what remains a caller responsibility in this iteration).
 *   3. The flows+credentials are staged into B via ONE full v2 POST
 *      /flows, exactly like lib/remoteDeployStorage.js - this alone does
 *      NOT make B active; nothing yet is watching B for new ingress.
 *   4. `readinessCheck(generation)` is awaited. Only if it resolves does
 *      the generation-manager (see lib/generationManager.js) atomically
 *      flip the active pointer, in a promotion serialized against any
 *      other concurrent Deploy for the same manager.
 *   5. If staging OR the readiness check fails, saveFlows() REJECTS
 *      (surfacing a normal Deploy error in the editor, exactly like the
 *      plain remoteDeployStorage's existing failure semantics) and the
 *      previously-active generation is left completely untouched -
 *      "keep A authoritative" (issue #105 P2/P5).
 *
 * This module intentionally does NOT:
 *   - decide what "active" means for ingress/control routing consumers
 *     (lib/remoteRuntimeAdminProxy.js, lib/remoteRuntimeEvents.js, source
 *     ingress owners) - it only maintains the single generationManager
 *     instance's active/draining bookkeeping. Wiring those consumers to
 *     read `manager.getActive().target` instead of a static target is a
 *     documented follow-up (see README).
 *   - spawn/supervise runner B's process - `buildGeneration` is expected
 *     to return a generation description for an ALREADY-STARTED B (started
 *     via the existing `worker --role activity --admin-port` CLI seam);
 *     see README for the manual/scripted provisioning step this replaces
 *     only the "deploy into a live runtime" half of.
 */

"use strict";

const { createRemoteDeployStorage } = require("./remoteDeployStorage");
const { createGenerationManager } = require("./generationManager");

/**
 * @param {object} delegate - the editor's existing (real) storageModule,
 *   exactly as accepted by createRemoteDeployStorage().
 * @param {object} options
 * @param {object} [options.manager] - a createGenerationManager() instance;
 *   defaults to a fresh private one (one manager per editor process is the
 *   documented model - issue #105's "serialize Deploy promotions for one
 *   editor").
 * @param {function(Array<object>, object): Promise<{id:string, flowVersion:string, activityTaskQueue:string, target:string, userDir?:string, token?:string}>} options.buildGeneration -
 *   builds THIS deploy's immutable generation description from the flows
 *   about to be saved and the freshly-read credential bundle.
 * @param {function(object): Promise<void>} options.readinessCheck - must
 *   resolve iff the built generation's runner is verified ready (issue
 *   #105 P2: live runtime + matching flowVersion/queue + Temporal
 *   polling + required listeners - process/HTTP-port existence ALONE is
 *   not sufficient, per the issue's explicit requirement).
 * @param {function} [options.fetch] - forwarded to the per-generation
 *   internal remoteDeployStorage instances used for staging.
 * @returns {object} a Node-RED-compatible storageModule; also exposes
 *   `getGenerationManager()` so callers (e.g. an Admin/routing proxy) can
 *   read the current active/draining generations.
 */
function createGracefulRemoteDeployStorage(delegate, options) {
    options = options || {};
    if (typeof options.buildGeneration !== "function") {
        throw new Error("gracefulDeployStorage requires options.buildGeneration(flows, credentials)");
    }
    if (typeof options.readinessCheck !== "function") {
        throw new Error("gracefulDeployStorage requires options.readinessCheck(generation)");
    }
    const manager = options.manager || createGenerationManager();
    const fetchImpl = options.fetch;

    /**
     * Stages `flows`+`credentials` into the generation's target via the
     * SAME full v2 POST /flows mechanics as lib/remoteDeployStorage.js -
     * built fresh per-call so each generation's `target`/`token` are used
     * without leaking state between generations.
     */
    async function stage(generation, flows, credentials) {
        // A throwaway delegate whose saveFlows() is a no-op: this reuses
        // createRemoteDeployStorage() purely for its deployToRemote()
        // POST-building logic (headers/no-rev/error-surfacing), without
        // re-running the (already-completed) local delegate save.
        const stagingDelegate = {
            saveFlows: async function() {},
            getCredentials: async function() { return credentials; }
        };
        const stagingAdapter = createRemoteDeployStorage(stagingDelegate, {
            target: generation.target,
            token: generation.token,
            fetch: fetchImpl
        });
        await stagingAdapter.saveFlows(flows);
    }

    return Object.assign({}, delegate, {
        async saveFlows(flows, user) {
            await delegate.saveFlows(flows, user);
            const credentials = await delegate.getCredentials();

            const generation = await options.buildGeneration(flows, credentials);
            if (!generation || !generation.id) {
                throw new Error("gracefulDeployStorage: buildGeneration() must return a generation with an id");
            }

            // Stage first - failing here never touches the active pointer.
            await stage(generation, flows, credentials);

            // Only a successful, serialized readiness-gated promote()
            // flips the active generation.
            await manager.promote(generation, function() {
                return options.readinessCheck(generation);
            });
        },
        getGenerationManager() {
            return manager;
        }
    });
}

module.exports = { createGracefulRemoteDeployStorage };
